(function(){
'use strict';
const originalFetch=window.fetch.bind(window);
const RULES=`אריאלה מנהלת שיחה טבעית כמו סוכנת נסיעות ולא שאלון. אין להציג קודים פנימיים, true/false או enum, ואין לשאול שוב מידע שכבר נמסר.
בחופשה רגילה: קודם אוספים יעד או בקשה שאריאלה תבחר, מועד, ומי נוסע. אחר כך ורק אחר כך אוספים את כל פרטי הטיסה: תקציב, כבודה, וישיר או קונקשן. אם פרט כבר נמסר לא שואלים אותו שוב. רק לאחר שכל פרטי הטיסה נאספו שואלים אם הלקוח רוצה שאריאלה תבנה את הטיול כולו או רק עזרה בדברים מסוימים. אין להציג לינה/רכב/אטרקציות/תכנון מסלול לפני השלמת פרטי הטיסה.
אם אריאלה בונה את הטיול: קודם תחומי עניין, אחר כך מסלול הגיוני, אחר כך לינה לפי המסלול, ורק אז רכב וימי/מקומות איסוף והחזרה. אם הלקוח רוצה עזרה נקודתית, ממשיכים רק לשירותים שביקש. ברכב משתמשים אוטומטית במספר הנוסעים ובכבודה שכבר ידועים כדי לסנן רכב קטן מדי.
תאריכים: תאריך מדויק נשמר; חודש פירושו כל החודש; סופ״ש = יציאה רביעי/חמישי וחזרה שבת/ראשון; שבוע = ראשון עד חמישי; תקופה כמו סוף אוקטובר נשמרת כתקופה. אין לשאול אוטומטית על גמישות או משך.
בסיום שאלי אם יש עוד משהו חשוב לפני החיפוש.
הביטויים "חופשה חדשה", "מהתחלה", "נתחיל מחדש" וביטויים ברורים מקבילים פותחים חופשה חדשה. מנקים את נתוני החופשה הפעילה בלבד; פרטי המשתמש והחופשות הקודמות נשמרים.`;
function isChat(input,init){const u=typeof input==='string'?input:(input&&input.url)||'';return /\/api\/ariella\/chat(?:\?|$)/.test(u)&&String((init&&init.method)||'GET').toUpperCase()==='POST';}
window.fetch=async function(input,init){if(isChat(input,init)&&init&&typeof init.body==='string'){try{const p=JSON.parse(init.body),m=String(p.message||'').trim();if(m){p.message=['הודעת הלקוח המקורית:',m,'',RULES].join('\n');init=Object.assign({},init,{body:JSON.stringify(p)});}}catch(e){}}return originalFetch(input,init);};
function isNew(text){return /^(?:מהתחלה|חופשה חדשה|נתחיל מחדש|להתחיל מחדש|בואי נתחיל מחדש|בואי נחפש משהו אחר)\s*[.!?]*$/i.test(String(text||'').trim());}
function flightComplete(){return ['destination','dates','travelers','budget','flight','baggage'].every(k=>document.querySelector(`#ariellaDesktopChat [data-summary-key="${k}"].is-filled`));}
function resetVacation(){try{['ariellaChatState:v3','ariellaChatState:v4'].forEach(k=>{localStorage.removeItem(k);sessionStorage.removeItem(k);});}catch(e){}document.querySelectorAll('#ariellaDesktopChat .ac-detail').forEach(r=>{r.classList.remove('is-filled');const s=r.querySelector('span');if(s)s.textContent=document.documentElement.lang==='en'?'Not specified yet':'עדיין לא צוין';});}
function tidy(){const c=document.getElementById('ariellaDesktopChat');if(!c)return;c.querySelectorAll('.ariella-new-chat').forEach(x=>x.remove());document.querySelectorAll('#vacationTypeGate,.vacation-type-gate').forEach(x=>x.style.setProperty('display','none','important'));c.querySelectorAll('.ac-flow-card').forEach(x=>{if(!flightComplete())x.remove();});}
function boot(){const st=document.createElement('style');st.textContent=`body.ariella-chat-preview-active #vacationTypeGate,body.ariella-chat-preview-active .vacation-type-gate{display:none!important}#ariellaDesktopChat .ariella-new-chat{display:none!important}@media(max-width:899px){#ariellaDesktopChat .ac-head{min-height:64px!important;padding:8px 12px!important;gap:9px!important;flex-wrap:nowrap!important}#ariellaDesktopChat .ac-avatar{width:44px!important;height:44px!important;flex:0 0 44px!important}#ariellaDesktopChat .ac-head-copy{min-width:0!important;flex:1!important}#ariellaDesktopChat .ac-head-copy strong{font-size:14px!important;line-height:1.2!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}#ariellaDesktopChat .ac-online{display:none!important}}`;document.head.appendChild(st);tidy();const c=document.getElementById('ariellaDesktopChat'),send=c?.querySelector('#ariellaChatSend'),inp=c?.querySelector('#ariellaChatInput');if(send&&inp){send.addEventListener('click',()=>{if(isNew(inp.value))resetVacation();},true);inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&isNew(inp.value))resetVacation();},true);}new MutationObserver(tidy).observe(document.body,{childList:true,subtree:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();